                "action": "test_probe", "by": "iter315", "started_at": "2026-09-05T11:00:00+00:00",
                "error": "simulasi iter315"
            }}})
            injected.append((coll, doc_id, was_pre))

        try:
            r = requests.get(f"{BASE_URL}/api/saga-locks", headers=admin_headers, timeout=15)
